  message(sprintf(
    "H07 LOSO START %s / %s / omit %s at %s",
    run$placement,
    run$metric_id,
    run$omitted_site,
    format(Sys.time(), "%Y-%m-%d %H:%M:%S")
  ))
  result &lt;- h07_run_metric(
