    na = ""
  )
  message(sprintf(
    "H07 LOSO DONE %s / %s / omit %s: %s",
    run$placement,
    run$metric_id,
    run$omitted_site,
    paste(unique(result$diagnostics$fit_status), collapse = ", ")
  ))
  rm(result, main_frame)
  invisible(gc())
}

